{"kind":"source-patchset","version":1,"disposition":"candidate","reason":"Stage A candidate only. It supplies diagnostics, package exports, host initialization and operation binding with the exact F-S11 staging seam; it does not implement the source view or claim owner acceptance.","changes":[{"operation":"create","path":"src/journal/diagnostics.mjs","text":"const instances = new WeakSet();
const privateDetails = new WeakMap();
const reasons = new Set([
  "source-corrupt",
  "evidence-unavailable",
  "resource-limit",
  "maintenance-busy",
  "storage-unsupported",
  "storage-unavailable",
  "publication-uncertain",
]);

export function journalUnavailable(reason, diagnostics) {
  if (!reasons.has(reason)) throw new TypeError("journal unavailable reason is invalid");
  const error = new Error(`journal unavailable: ${reason}`);
  error.name = "JournalUnavailable";
  error.code = "JOURNAL_UNAVAILABLE";
  error.reason = reason;
  Object.freeze(error.name);
  Object.freeze(error.code);
  Object.freeze(error.reason);
  Object.freeze(error);
  instances.add(error);
  privateDetails.set(error, diagnostics);
  return error;
}

export function isJournalUnavailable(value) {
  return value !== null && (typeof value === "object" || typeof value === "function")
    && instances.has(value);
}
