  closeSync,
  fstatSync,
  fsyncSync,
  lstatSync,
  openSync,
  readFileSync,
  statfsSync,
} from "node:fs";
import { spawnSync } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import path from "node:path";
import { constants as fsConstants } from "node:fs";
import { canonicalJson } from "@red-cup-engineering/json-services-section";
import { writeFileAtomicNew } from "../filesystem.mjs";
import { journalUnavailable } from "../diagnostics.mjs";

const HOST_NAME = "host.json";
const LOCK_NAME = "maintenance.lock";
const HOST_KIND = "metroplat.journal.host";
const HOST_LIMIT = 16384;
const locksInUse = new Set();
const O_NOFOLLOW = fsConstants.O_NOFOLLOW;
const O_DIRECTORY = fsConstants.O_DIRECTORY;
const O_CLOEXEC = fsConstants.O_CLOEXEC ?? 0;

function unavailable(reason, operation, cause) {
  return journalUnavailable(reason, Object.freeze({ operation, cause }));
}

function ioFailure(error, operation) {
  if (error?.code === "EOPNOTSUPP" || error?.code === "ENOTSUP" || error?.code === "ENOSYS") {
    return unavailable("storage-unsupported", operation, error);
  }
  return unavailable("storage-unavailable", operation, error);
}

function sameIdentity(left, right) {
  return left.dev === right.dev && left.ino === right.ino;
}

function pathComponents(absolutePath) {
  const parsed = path.parse(absolutePath);
  const parts = absolutePath.slice(parsed.root.length).split(path.sep).filter(Boolean);
  return [parsed.root, ...parts.map((part, index) => path.join(parsed.root, ...parts.slice(0, index + 1)))];
}

function bindDirectory(directory) {
  if (typeof directory !== "string" || !path.isAbsolute(directory)) {
    throw unavailable("storage-unavailable", "root-argument", new TypeError("absolute root required"));
  }
  const resolved = path.resolve(directory);
  const identities = [];
  let previous = null;
  for (const component of pathComponents(resolved)) {
    let named;
    let fd;
    try {
      named = lstatSync(component);
      if (named.isSymbolicLink() || !named.isDirectory()) {
        throw unavailable("storage-unavailable", "root-binding", new TypeError("root component is not a nonsymlink directory"));
      }
      fd = openSync(component, fsConstants.O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
      const opened = fstatSync(fd);
      if (!opened.isDirectory() || !sameIdentity(named, opened)) {
        throw unavailable("storage-unavailable", "root-binding", new Error("directory identity changed"));
      }
      if (previous && !sameIdentity(fstatSync(previous), lstatSync(path.dirname(component)))) {
        throw unavailable("storage-unavailable", "root-binding", new Error("directory ancestry changed"));
      }
      identities.push(Object.freeze({ path: component, dev: opened.dev, ino: opened.ino }));
      if (previous !== null) closeSync(previous);
      previous = fd;
      fd = null;
    } catch (error) {
      if (fd !== null && fd !== undefined) try { closeSync(fd); } catch {}
      if (previous !== null) try { closeSync(previous); } catch {}
      if (error?.code === "JOURNAL_UNAVAILABLE") throw error;
      throw ioFailure(error, "root-binding");
    }
  }
  if (previous !== null) closeSync(previous);
  const root = identities[identities.length - 1];
  let fsType;
  try {
    fsType = statfsSync(resolved).type;
  } catch (error) {
    throw ioFailure(error, "filesystem-profile");
  }
  if (process.platform !== "linux" || fsType !== 0xef53) {
    throw unavailable("storage-unsupported", "filesystem-profile", Object.freeze({ platform: process.platform, fsType }));
  }
  return Object.freeze({ path: resolved, dev: root.dev, ino: root.ino, identities: Object.freeze(identities) });
}

function assertRoot(root) {
  for (const expected of root.identities) {
    let named;
    let fd;
    try {
      named = lstatSync(expected.path);
      if (named.isSymbolicLink() || !named.isDirectory()) throw new Error("bound directory changed type");
      fd = openSync(expected.path, fsConstants.O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
      const opened = fstatSync(fd);
      if (!sameIdentity(expected, opened) || !sameIdentity(named, opened)) throw new Error("bound directory identity changed");
    } catch (error) {
      if (error?.code === "JOURNAL_UNAVAILABLE") throw error;
      throw ioFailure(error, "root-revalidation");
    } finally {
      if (fd !== null && fd !== undefined) try { closeSync(fd); } catch {}
    }
  }
}

function validateConfiguration(configuration) {
  const keys = ["hostProfile", "journal", "kind", "limits", "version"].sort();
  if (configuration === null || Array.isArray(configuration) || typeof configuration !== "object"
    || Object.keys(configuration).sort().join("\0") !== keys.join("\0")) {
    throw new TypeError("journal-host-invalid");
  }
  if (configuration.kind !== HOST_KIND || configuration.version !== 1
    || typeof configuration.journal !== "string" || configuration.journal.length === 0
    || [...configuration.journal].length > 512) throw new TypeError("journal-host-invalid");
  for (let i = 0; i < configuration.journal.length; i += 1) {
    const unit = configuration.journal.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = configuration.journal.charCodeAt(i + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) throw new TypeError("journal-host-invalid");
      i += 1;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) throw new TypeError("journal-host-invalid");
  }
  const limitKeys = ["maxLineBytes", "maxBatchBytes", "maxSourceFiles", "maxScanBytes", "maxClosureWitnesses", "maxClosureArtifacts", "maxClosureBytes", "maxClosureDepth"].sort();
  const limits = configuration.limits;
  if (limits === null || Array.isArray(limits) || typeof limits !== "object"
    || Object.keys(limits).sort().join("\0") !== limitKeys.join("\0")
    || Object.values(limits).some((value) => !Number.isSafeInteger(value) || value <= 0)
    || limits.maxLineBytes > limits.maxBatchBytes || limits.maxBatchBytes > limits.maxScanBytes) {
    throw new TypeError("journal-host-invalid");
  }
  if (configuration.hostProfile !== "linux-local-flock-v1") {
    throw unavailable("storage-unsupported", "host-profile", configuration.hostProfile);
  }
  const frozenLimits = Object.freeze({ ...limits });
  const admitted = Object.freeze({ kind: HOST_KIND, version: 1, journal: configuration.journal, hostProfile: configuration.hostProfile, limits: frozenLimits });
  const bytes = `${canonicalJson(admitted)}\n`;
  if (Buffer.byteLength(bytes, "utf8") > HOST_LIMIT) throw new TypeError("journal-host-invalid");
  return Object.freeze({ configuration: admitted, bytes });
}

function readHost(root) {
  assertRoot(root);
  const hostPath = path.join(root.path, HOST_NAME);
  let st;
  try {
    st = lstatSync(hostPath);
  } catch (error) {
    if (error?.code === "ENOENT") throw unavailable("storage-unavailable", "host-unconfigured", error);
    throw ioFailure(error, "host-read");
  }
  if (st.isSymbolicLink() || !st.isFile() || st.size > HOST_LIMIT) {
    throw unavailable("source-corrupt", "host-file", new Error("host file is not a bounded regular file"));
  }
  let fd;
  try {
    fd = openSync(hostPath, fsConstants.O_RDONLY | O_NOFOLLOW | O_CLOEXEC);
    const opened = fstatSync(fd);
    if (!opened.isFile() || !sameIdentity(st, opened) || opened.size > HOST_LIMIT) throw new Error("host identity or size changed");
    const bytes = readFileSync(fd);
    if (bytes.length > HOST_LIMIT) throw new Error("host exceeds byte limit");
    const text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    const value = JSON.parse(text);
    const admitted = validateConfiguration(value);
    if (admitted.bytes !== text) throw new Error("host bytes are not canonical");
    return Object.freeze({ bytes: Buffer.from(bytes), digest: createHash("sha256").update(bytes).digest("hex"), configuration: admitted.configuration, identity: Object.freeze({ dev: opened.dev, ino: opened.ino }) });
  } catch (error) {
    if (error?.code === "JOURNAL_UNAVAILABLE") throw error;
    throw unavailable("source-corrupt", "host-admission", error);
  } finally {
    if (fd !== null && fd !== undefined) closeSync(fd);
  }
}

function openLock(root) {
  const lockPath = path.join(root.path, LOCK_NAME);
  let fd;
  try {
    fd = openSync(lockPath, fsConstants.O_RDWR | fsConstants.O_CREAT | O_NOFOLLOW | O_CLOEXEC, 0o600);
    const st = fstatSync(fd);
    if (!st.isFile()) throw new Error("maintenance lock is not a regular file");
    const named = lstatSync(lockPath);
    if (named.isSymbolicLink() || !named.isFile() || !sameIdentity(st, named)) throw new Error("maintenance lock identity changed");
    return Object.freeze({ fd, dev: st.dev, ino: st.ino });
  } catch (error) {
    if (fd !== null && fd !== undefined) try { closeSync(fd); } catch {}
    if (error?.code === "ELOOP" || error?.code === "ENOTDIR") throw unavailable("storage-unavailable", "lock-binding", error);
    throw ioFailure(error, "lock-open");
  }
}

function acquire(lock) {
  const key = `${lock.dev}:${lock.ino}`;
  if (locksInUse.has(key)) throw unavailable("maintenance-busy", "reentrant-operation", key);
  locksInUse.add(key);
  try {
    const result = spawnSync("/usr/bin/flock", ["--exclusive", "--nonblock", "3"], {
      stdio: ["ignore", "ignore", "pipe", lock.fd],
      encoding: "utf8",
      timeout: 10000,
      maxBuffer: 4096,
    });
    if (result.error) {
      if (result.error.code === "ETIMEDOUT") throw unavailable("storage-unsupported", "flock-timeout", result.error);
      throw ioFailure(result.error, "flock");
    }
    if (result.status === 1) throw unavailable("maintenance-busy", "flock-contention", result.stderr);
    if (result.status !== 0) throw unavailable("storage-unavailable", "flock-failure", result.stderr);
    return () => locksInUse.delete(key);
  } catch (error) {
    locksInUse.delete(key);
    throw error;
  }
}

function assertBindings(root, lock, host) {
  assertRoot(root);
  let lockStat;
  try {
    lockStat = fstatSync(lock.fd);
    const named = lstatSync(path.join(root.path, LOCK_NAME));
    if (!named.isFile() || named.isSymbolicLink() || !sameIdentity(lock, lockStat) || !sameIdentity(lock, named)) throw new Error("lock binding changed");
  } catch (error) {
    throw ioFailure(error, "lock-revalidation");
  }
  const current = readHost(root);
  if (!sameIdentity(host.identity, current.identity) || host.digest !== current.digest) {
    throw unavailable("storage-unavailable", "host-binding-changed", new Error("host identity or bytes changed"));
  }
}

function withGate(root, callback) {
  const lock = openLock(root);
  let releaseRegistry;
  let gateHeld = false;
  try {
    releaseRegistry = acquire(lock);
    gateHeld = true;
    return callback(lock, () => assertBindings(root, lock, readHost(root)));
  } finally {
    if (gateHeld) releaseRegistry();
    closeSync(lock.fd);
  }
}

function createSourceScope(operation) {
  throw new TypeError("journal source view fabrication incomplete");
}

export function openSourceOwner(storeDirectory) {
  const root = bindDirectory(storeDirectory);
  let lock = openLock(root);
  let host;
  let releaseRegistry;
  try {
    releaseRegistry = acquire(lock);
    assertRoot(root);
    host = readHost(root);
    assertBindings(root, lock, host);
  } finally {
    if (releaseRegistry) releaseRegistry();
    closeSync(lock.fd);
  }
  let invalidated = false;
  const owner = Object.freeze({
    withOperation(perform) {
      if (typeof perform !== "function") throw new TypeError("journal operation callback is invalid");
      if (invalidated) throw unavailable("storage-unavailable", "owner-invalidated");
      let heldLock;
      let release;
      let live = true;
      let publicationPossible = false;
      let callbackStarted = false;
      let callbackResult;
      let callbackError;
      let callbackFailed = false;
      try {
        heldLock = openLock(root);
        release = acquire(heldLock);
        assertBindings(root, heldLock, host);
        const operation = Object.freeze({
          root: root.path,
          configuration: host.configuration,
          cache: { value: undefined },
          assertLive() { if (!live) throw new TypeError("journal operation scope expired"); },
          assertBindings() {
            if (!live) throw new TypeError("journal operation scope expired");
            try { assertBindings(root, heldLock, host); } catch (error) { invalidated = true; throw error; }
          },
          markPublicationPossible() { if (!live) throw new TypeError("journal operation scope expired"); publicationPossible = true; },
        });
        operation.assertBindings();
        const scope = createSourceScope(operation);
        callbackStarted = true;
        try {
          callbackResult = perform(scope);
          if (callbackResult !== null && (typeof callbackResult === "object" || typeof callbackResult === "function")
            && typeof callbackResult.then === "function") throw new TypeError("journal operation callback must be synchronous");
        } catch (error) {
          callbackFailed = true;
          callbackError = error;
        }
        operation.assertBindings();
        if (callbackFailed) {
          if (publicationPossible) throw unavailable("publication-uncertain", "operation-acknowledgment", callbackError);
          throw callbackError;
        }
        return callbackResult;
      } catch (error) {
        if (error?.reason === "storage-unavailable" && error?.message === "journal unavailable: storage-unavailable") invalidated = true;
        if (publicationPossible) throw unavailable("publication-uncertain", "operation-acknowledgment", error);
        if (callbackStarted && callbackFailed && error === callbackError) throw error;
        if (error?.code === "JOURNAL_UNAVAILABLE" || error instanceof TypeError) throw error;
        throw ioFailure(error, "operation");
      } finally {
        live = false;
        if (release) release();
        if (heldLock) closeSync(heldLock.fd);
      }
    },
  });
  return owner;
}

export function initializeJournal(storeDirectory, configuration) {
  const admitted = validateConfiguration(configuration);
  const root = bindDirectory(storeDirectory);
  return withGate(root, (lock) => {
    assertRoot(root);
    const hostPath = path.join(root.path, HOST_NAME);
    let existing;
    try {
      existing = lstatSync(hostPath);
    } catch (error) {
      if (error?.code !== "ENOENT") throw ioFailure(error, "host-initialize-check");
    }
    if (existing) {
      const current = readHost(root);
      if (!current.bytes.equals(Buffer.from(admitted.bytes, "utf8"))) {
        throw unavailable("storage-unavailable", "host-configuration-conflict");
      }
      assertRoot(root);
      try {
        writeFileAtomicNew(hostPath, admitted.bytes, { mode: 0o600, durable: true });
      } catch (error) {
        if (error?.code !== "EEXIST") throw ioFailure(error, "host-existing-durability");
      }
      return Object.freeze({ disposition: "existing", journal: admitted.configuration.journal });
    }
    let publicationEntered = false;
    try {
      assertRoot(root);
      publicationEntered = true;
      writeFileAtomicNew(hostPath, admitted.bytes, { mode: 0o600, durable: true });
      const current = readHost(root);
      if (!current.bytes.equals(Buffer.from(admitted.bytes, "utf8"))) throw new Error("published host differs from proposal");
      assertRoot(root);
      return Object.freeze({ disposition: "created", journal: admitted.configuration.journal });
    } catch (error) {
      if (publicationEntered) throw unavailable("publication-uncertain", "host-publication", error);
      throw error;
    }
  });
}
